void post_rx(Desc* d, dma_addr_t buf, uint16_t len) {
  d->addr = buf;
  d->len = len;
  d->flags = DESC_OWN_HW;
  writel(next_idx, dev->rx_tail);
}

void post_tx(struct ring* r, dma_addr_t buf, u16 len) {
  struct desc* d = &r->desc[r->tail];
  d->addr = cpu_to_le64(buf);
  d->len  = cpu_to_le16(len);
  dma_wmb();
  d->flags = cpu_to_le16(DESC_OWN_HW);
  r->tail = (r->tail + 1) & r->mask;
  writel_relaxed(r->tail, r->db_reg);
}
